/*
 * ATT signed-write truncation transform, demonstrated on an externally
 * published constant.
 *
 * SOURCE VALUE: [SPEC] Vol 3, Part H, Appendix D.1.2 AES_CMAC
 * (= RFC 4493 Section 4 Example 2), reproduced above as
 * bt_extref_rfc4493_ex2_cmac, in spec display order (MSB first).
 *
 * TRANSFORM: this is BlueZ bt_crypto_sign_att()'s tail, applied by hand
 * to that constant.  It is PURE BYTE REORDERING of a published value;
 * no cipher was run to obtain it, and it is NOT claimed to be the
 * signature of any particular ATT PDU (BlueZ byte-swaps the message
 * before the CMAC, so the CMAC input differs from RFC 4493's).
 *
 *   out[0..15] = 07 0a 16 b4 6b 4d 41 44 f7 9b dd 9d d0 4a 28 7c
 *   put_be32(1, out + 8)  overwrites out[8..11] with 00 00 00 01:
 *   out[0..15] = 07 0a 16 b4 6b 4d 41 44 00 00 00 01 d0 4a 28 7c
 *   swap_buf(out, tmp, 16) gives tmp[i] = out[15 - i]:
 *   tmp[0..15] = 7c 28 4a d0 01 00 00 00 44 41 4d 6b b4 16 0a 07
 *   signature  = tmp[4..15]
 *              = 01 00 00 00 44 41 4d 6b b4 16 0a 07
 *
 * So signature[0..3] is the sign counter in LITTLE-endian order and
 * signature[4..11] is out[7..0]: the most significant 8 CMAC octets,
 * reversed.  The least significant 4 CMAC octets out[12..15] are
 * discarded entirely.
 */
/* DERIVED by hand from bt_extref_rfc4493_ex2_cmac; see comment above */
static const uint8_t bt_extref_sign_trunc_demo_sig[12] = {
	0x01, 0x00, 0x00, 0x00, 0x44, 0x41, 0x4d, 0x6b,
	0xb4, 0x16, 0x0a, 0x07,
};

#define BT_EXTREF_SIGN_TRUNC_DEMO_SIGN_CNT 1
#define BT_EXTREF_SIGN_TRUNC_DEMO_MAC_OFFSET 4
#define BT_EXTREF_SIGN_TRUNC_DEMO_MAC_LEN 8

